import React, { useState } from 'react';
import API from '../api/axiosClient';
import { useMutation, useQuery } from '@tanstack/react-query';
import { FaCreditCard, FaCashRegister, FaCheckCircle, FaUserShield, FaClock } from 'react-icons/fa';
import CompanyTransactions from '../components/CompanyTransactions';

export default function WorkerDashboard({ orgId, machineId, userRole }) {
    const [rfidUid, setRfidUid] = useState('');
    const [customerEmail, setCustomerEmail] = useState('');
    const [chargeEmail, setChargeEmail] = useState('');
    const [chargeAmount, setChargeAmount] = useState('');
    const [promoteEmail, setPromoteEmail] = useState('');
    const [newRole, setNewRole] = useState('admin');
    const [feedback, setFeedback] = useState('');

    // Fetch active pending charges ("in-progress" status for worker view)
    const { data: activePending = [] } = useQuery({
        queryKey: ['activePending', orgId],
        queryFn: async () => {
            const res = await API.get(`/worker/${orgId}/pending`);
            return res.data;
        },
        refetchInterval: 3000 // Poll every 3 seconds for live tap confirmation updates
    });

    const assignMutation = useMutation({
        mutationFn: async (data) => await API.post(`/worker/${orgId}/assign-card`, data),
        onSuccess: (res) => { setFeedback(res.data.message); setCustomerEmail(''); setRfidUid(''); },
        onError: (err) => setFeedback(err.response?.data?.error || 'Failed to assign card'),
    });

    const chargeMutation = useMutation({
        mutationFn: async (data) => await API.post(`/worker/${orgId}/charge`, data),
        onSuccess: (res) => { 
            setFeedback(res.data.message); 
            setChargeEmail(''); 
            setChargeAmount(''); 
        },
        onError: (err) => setFeedback(err.response?.data?.error || 'Failed to process charge')
    });

    const roleMutation = useMutation({
        mutationFn: async (data) => await API.post(`/worker/${orgId}/update-role`, data),
        onSuccess: (res) => { setFeedback(res.data.message); setPromoteEmail(''); },
        onError: (err) => setFeedback(err.response?.data?.error || 'Failed to update user role')
    });
    console.log(activePending)
    return (
        <div className="space-y-8">
            <h1 className="text-3xl font-bold flex items-center gap-2">
                <FaCashRegister className="text-indigo-400" /> Terminal & Management Dashboard
            </h1>

            {feedback && (
                <div className="p-4 bg-indigo-950 border border-indigo-700/50 rounded-xl text-indigo-200 shadow-lg">
                    {feedback}
                </div>
            )}

            {/* Active In-Progress Charges Section */}
            <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-xl">
                <h2 className="text-xl font-semibold mb-4 flex items-center gap-2 text-amber-400">
                    <FaClock /> Awaiting Terminal Taps (In-Progress)
                </h2>
                {activePending.length === 0 ? (
                    <p className="text-gray-400 text-sm">No charges currently pending a physical card tap.</p>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        {activePending.map((item) => (
                            <div key={item.userId} className="flex justify-between items-center bg-gray-900 p-4 rounded-lg border border-amber-500/30">
                                <div>
                                    <p className="font-semibold text-white">Amount: ${item.amount}</p>
                                    <p className="text-xs text-gray-400">Machine: {item.email}</p>
                                </div>
                                <span className="bg-amber-500/20 text-amber-400 border border-amber-500/40 text-xs px-2.5 py-1 rounded-full font-bold uppercase tracking-wider animate-pulse">
                                    {item.status}
                                </span>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {/* Card Assignment Card */}
                <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-xl">
                    <h2 className="text-xl font-semibold mb-4 flex items-center gap-2">
                        <FaCreditCard className="text-indigo-400" /> Link RFID Card
                    </h2>
                    <div className="space-y-4">
                        <input 
                            type="email" placeholder="Customer Email" value={customerEmail}
                            onChange={(e) => setCustomerEmail(e.target.value)}
                            className="w-full p-3 bg-gray-900 border border-gray-700 rounded-lg text-white"
                        />
                        <input 
                            type="text" placeholder="RFID UID (e.g. A4B2C103)" value={rfidUid}
                            onChange={(e) => setRfidUid(e.target.value)}
                            className="w-full p-3 bg-gray-900 border border-gray-700 rounded-lg text-white"
                        />
                        <button 
                            onClick={() => assignMutation.mutate({ email: customerEmail, rfidUid })}
                            className="w-full bg-indigo-600 hover:bg-indigo-500 p-3 rounded-lg font-semibold transition"
                        >
                            Link Card
                        </button>
                    </div>
                </div>

                {/* Charge Terminal Card (Using Email) */}
                <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-xl">
                    <h2 className="text-xl font-semibold mb-4 flex items-center gap-2">
                        <FaCheckCircle className="text-emerald-400" /> Process Purchase
                    </h2>
                    <div className="space-y-4">
                        <input 
                            type="email" placeholder="Customer Email" value={chargeEmail}
                            onChange={(e) => setChargeEmail(e.target.value)}
                            className="w-full p-3 bg-gray-900 border border-gray-700 rounded-lg text-white"
                        />
                        <input 
                            type="number" placeholder="Amount ($)" value={chargeAmount}
                            onChange={(e) => setChargeAmount(e.target.value)}
                            className="w-full p-3 bg-gray-900 border border-gray-700 rounded-lg text-white"
                        />
                        <button 
                            onClick={() => chargeMutation.mutate({ machineId, email: chargeEmail, amount: parseFloat(chargeAmount) })}
                            className="w-full bg-emerald-600 hover:bg-emerald-500 p-3 rounded-lg font-semibold transition"
                        >
                            Charge Customer
                        </button>
                    </div>
                </div>

                {/* Admin-Only Role Management Card */}
                {userRole === 'admin' && (
                    <div className="bg-gray-800 p-6 rounded-xl border border-purple-700/50 shadow-xl md:col-span-2 lg:col-span-1">
                        <h2 className="text-xl font-semibold mb-4 flex items-center gap-2 text-purple-400">
                            <FaUserShield /> Promote User Role
                        </h2>
                        <div className="space-y-4">
                            <input 
                                type="email" placeholder="User Email" value={promoteEmail}
                                onChange={(e) => setPromoteEmail(e.target.value)}
                                className="w-full p-3 bg-gray-900 border border-gray-700 rounded-lg text-white"
                            />
                            <select 
                                value={newRole} onChange={(e) => setNewRole(e.target.value)}
                                className="w-full p-3 bg-gray-900 border border-gray-700 rounded-lg text-white"
                            >
                                <option value="worker">Worker</option>
                                <option value="admin">Admin</option>
                                <option value="customer">Customer</option>
                            </select>
                            <button 
                                onClick={() => roleMutation.mutate({ email: promoteEmail, newRole })}
                                className="w-full bg-purple-600 hover:bg-purple-500 p-3 rounded-lg font-semibold transition"
                            >
                                Update Role
                            </button>
                        </div>
                    </div>
                )}
            </div>

            <CompanyTransactions orgId={orgId} />
        </div>
    );
}
